/*
 * File:  bsp_start.c
 *
 * Purpose:
 *   Host-independent FreeRTOS OSAL BSP entry point and support code, shared
 *   across every FreeRTOS host-specific BSP (e.g. the POSIX simulator port).
 *   Each consumer compiles this file itself against its own
 *   FreeRTOSConfigPlatform.h (generated by osal_freertos_platform()), since
 *   some of the code below sizes static buffers from config values that
 *   legitimately differ per host.
 */

#include <stddef.h>
#include <stdlib.h>
#include <string.h>

#include "FreeRTOS.h"
#include "task.h"
#include "timers.h"
#include "semphr.h"

#include "osapi-common.h"
#include "bsp-impl.h"

#include "generic_freertos_bsp_internal.h"
#include "bsp_storage.h"

OS_BSP_GenericFreeRTOSGlobalData_t OS_BSP_GenericFreeRTOSGlobal;

/*----------------------------------------------------------------
   OS_BSP_MaskAllInterrupts

   Stops every maskable interrupt (on a POSIX host, every signal) on the
   calling CPU/thread, and is never undone. On Cortex-M it also stops SysTick
   and clears what is pending, so the halt loop can sleep, see below.
   taskDISABLE_INTERRUPTS() is not used because each FreeRTOS port defines it
   differently: the ARMv7-M and later ports only raise BASEPRI, which leaves
   higher-priority interrupts running.

   The port's family comes from the macro it names in
   generic-freertos/config/CMakeLists.txt, which rejects a PORT it does not know:
   every Cortex-M port names OSAL_FREERTOS_PORT_CORTEX_M, and anything else is
   the POSIX simulator. NMI and HardFault cannot be masked on any ARM core: the halt loop cannot
   cause a HardFault, and each ARM platform should point both vectors at a
   spin loop in its startup code.
 ------------------------------------------------------------------*/
#if defined(OSAL_FREERTOS_PORT_CORTEX_M)

/* System Control Space registers, at the same address on every Cortex-M */
#define OS_BSP_SYST_CSR         (*(volatile uint32_t *)0xE000E010UL)
#define OS_BSP_ICSR             (*(volatile uint32_t *)0xE000ED04UL)
#define OS_BSP_NVIC_ICER(Index) (*(volatile uint32_t *)(0xE000E180UL + (4UL * (Index))))
#define OS_BSP_NVIC_ICPR(Index) (*(volatile uint32_t *)(0xE000E280UL + (4UL * (Index))))

#define OS_BSP_ICSR_PENDSVCLR (1UL << 27)
#define OS_BSP_ICSR_PENDSTCLR (1UL << 25)

/* Armv6-M has 32 interrupts in one register, the later cores up to 480 in 16 */
#if defined(__ARM_ARCH_6M__)
#define OS_BSP_NVIC_REGISTERS 1UL
#else
#define OS_BSP_NVIC_REGISTERS 16UL
#endif

static inline void OS_BSP_MaskAllInterrupts(void)
{
    uint32_t Index;

    /* PRIMASK masks every configurable interrupt, whatever its priority */
    __asm volatile("cpsid i" ::: "memory");

    /*
     * A masked interrupt that is pending still wakes WFI, and WFI returns at
     * once if one is already pending. SysTick sets its pending bit on every
     * tick, so the halt loop in OS_BSP_Halt would spin at full speed instead of
     * sleeping. Stopping SysTick and PendSV and disabling and clearing every
     * NVIC interrupt leaves nothing that can become pending.
     */
    OS_BSP_SYST_CSR = 0U;
    OS_BSP_ICSR     = OS_BSP_ICSR_PENDSTCLR | OS_BSP_ICSR_PENDSVCLR;
    for (Index = 0U; Index < OS_BSP_NVIC_REGISTERS; Index++)
    {
        OS_BSP_NVIC_ICER(Index) = 0xFFFFFFFFUL;
        OS_BSP_NVIC_ICPR(Index) = 0xFFFFFFFFUL;
    }
}

static inline void OS_BSP_HaltWait(void)
{
    /* Sleeps the core until an event; returns at once if an interrupt is already pending */
    __asm volatile("wfi" ::: "memory");
}

#else

#include <pthread.h>
#include <signal.h>
#include <unistd.h>

static inline void OS_BSP_MaskAllInterrupts(void)
{
    sigset_t AllSignals;

    /* The GCC_POSIX port's tick is SIGALRM, so blocking every signal on this thread stops it */
    (void)sigfillset(&AllSignals);
    (void)pthread_sigmask(SIG_BLOCK, &AllSignals, NULL);
}

static inline void OS_BSP_HaltWait(void)
{
    /* Every signal is blocked on this thread, so this sleeps until the process is killed */
    (void)pause();
}

#endif

/*----------------------------------------------------------------
   OS_BSP_ReportString / OS_BSP_ReportNumber

   Write to the console through OS_BSP_ConsoleOutput_Impl only: no
   OS_printf, no console lock and no heap, since the assert handler can run
   from an ISR, a critical section or the middle of a semaphore operation.
 ------------------------------------------------------------------*/
static inline void OS_BSP_ReportString(const char *Str)
{
    OS_BSP_ConsoleOutput_Impl(Str, strlen(Str));
}

static inline void OS_BSP_ReportNumber(int Number)
{
    char         Digits[11];
    size_t       Pos   = sizeof(Digits);
    unsigned int Value = (Number < 0) ? 0U : (unsigned int)Number;

    do
    {
        Pos--;
        Digits[Pos]  = (char)('0' + (Value % 10U));
        Value       /= 10U;
    } while (Value != 0U);

    OS_BSP_ConsoleOutput_Impl(&Digits[Pos], sizeof(Digits) - Pos);
}

/*----------------------------------------------------------------
   OS_BSP_BeginHalt / OS_BSP_Halt

   Shared by every fatal path. BeginHalt masks interrupts and reports whether
   this is the first fatal error: one raised while reporting another skips the
   report and goes straight to Halt, so the halt is always reached. The flag is
   set before anything is reported. Halt never returns, but sleeps through
   OS_BSP_HaltWait instead of spinning, so a halted system does not use the CPU.
 ------------------------------------------------------------------*/
static inline bool OS_BSP_BeginHalt(void)
{
    bool First;

    OS_BSP_MaskAllInterrupts();

    First                                = !OS_BSP_GenericFreeRTOSGlobal.Halting;
    OS_BSP_GenericFreeRTOSGlobal.Halting = true;

    return First;
}

__attribute__((noreturn)) static inline void OS_BSP_Halt(void)
{
    for (;;)
    {
        OS_BSP_HaltWait();
    }
}

/*----------------------------------------------------------------
   OS_FreeRTOS_AssertFailed

   Called by configASSERT (see FreeRTOSConfig.h). Masks interrupts, reports
   File:Line and halts. Never returns.
 ------------------------------------------------------------------*/
void OS_FreeRTOS_AssertFailed(const char *File, int Line)
{
    if (OS_BSP_BeginHalt())
    {
        OS_BSP_ReportString("ASSERT ");
        OS_BSP_ReportString(File);
        OS_BSP_ReportString(":");
        OS_BSP_ReportNumber(Line);
        OS_BSP_ReportString("\n");
    }

    OS_BSP_Halt();
}

/*----------------------------------------------------------------
   OS_FreeRTOS_StackOverflow

   Called by vApplicationStackOverflowHook, which the kernel calls from inside
   its task switch. The kernel's state cannot be changed there, so it masks
   interrupts, reports the task and halts. Never returns.
 ------------------------------------------------------------------*/
__attribute__((noreturn)) static void OS_FreeRTOS_StackOverflow(const char *TaskName)
{
    if (OS_BSP_BeginHalt())
    {
        OS_BSP_ReportString("STACK OVERFLOW ");
        OS_BSP_ReportString(TaskName);
        OS_BSP_ReportString("\n");
    }

    OS_BSP_Halt();
}

#if !defined(OSAL_FREERTOS_PORT_ENDS_SCHEDULER)
/*----------------------------------------------------------------
   OS_FreeRTOS_ApplicationExit

   Called by OS_BSP_Exit on ports that cannot end the scheduler (the Cortex-M
   ports assert in vPortEndScheduler), so there is nothing to return to. Masks
   interrupts, reports the exit status (already translated to 0..127) and
   halts. Never returns.
 ------------------------------------------------------------------*/
__attribute__((noreturn)) static void OS_FreeRTOS_ApplicationExit(int Status)
{
    if (OS_BSP_BeginHalt())
    {
        OS_BSP_ReportString("APPLICATION EXIT ");
        OS_BSP_ReportNumber(Status);
        OS_BSP_ReportString("\n");
    }

    OS_BSP_Halt();
}
#endif

/*----------------------------------------------------------------
   OS_BSP_Lock_Impl
   See full description in header
 ------------------------------------------------------------------*/
void OS_BSP_Lock_Impl(void)
{
    xSemaphoreTake(OS_BSP_GenericFreeRTOSGlobal.ConsoleMutex, portMAX_DELAY);
}

/*----------------------------------------------------------------
   OS_BSP_Unlock_Impl
   See full description in header
 ------------------------------------------------------------------*/
void OS_BSP_Unlock_Impl(void)
{
    xSemaphoreGive(OS_BSP_GenericFreeRTOSGlobal.ConsoleMutex);
}

/*----------------------------------------------------------------
   OS_BSP_GetReturnStatus()

    Helper function to convert an OSAL status code into
    a code suitable for returning to the OS.
 ------------------------------------------------------------------*/
static int OS_BSP_GetReturnStatus(void)
{
    int retcode;

    switch (OS_BSP_Global.AppStatus)
    {
        case OS_SUCCESS:
            retcode = EXIT_SUCCESS;
            break;

        case OS_ERROR:
            retcode = EXIT_FAILURE;
            break;

        default:
            retcode = OS_BSP_Global.AppStatus & 0x7F;
            break;
    }

    return retcode;
}

/*----------------------------------------------------------------
   OS_BSP_Exit

    Ends the application. A port that implements vPortEndScheduler (the
    GCC_POSIX port, which returns control to main()) ends the scheduler.
    Every other port has nothing to return to (the Cortex-M ports assert in
    vPortEndScheduler), so it reports the status and halts. A port says it can
    end the scheduler through OSAL_FREERTOS_PORT_ENDS_SCHEDULER, defined per
    port in generic-freertos/config/CMakeLists.txt.
 ------------------------------------------------------------------*/
static inline void OS_BSP_Exit(int Status)
{
#if defined(OSAL_FREERTOS_PORT_ENDS_SCHEDULER)
    (void)Status;

    vTaskEndScheduler();
#else
    OS_FreeRTOS_ApplicationExit(Status);
#endif
}

/*----------------------------------------------------------------
   OS_BSP_Shutdown_Impl
   See full description in header
 ------------------------------------------------------------------*/
void OS_BSP_Shutdown_Impl(void)
{
    OS_BSP_Exit(OS_BSP_GetReturnStatus());
}

/*----------------------------------------------------------------
   FreeRTOS static-allocation hooks

   Required because FreeRTOSConfig.h sets configSUPPORT_STATIC_ALLOCATION
   and configCHECK_FOR_STACK_OVERFLOW - FreeRTOS calls these rather than
   allocating the idle/timer task memory itself, and reports a detected
   stack overflow through the hook instead of a fixed action.
 ------------------------------------------------------------------*/
void vApplicationGetIdleTaskMemory(StaticTask_t          **ppxIdleTaskTCBBuffer,
                                   StackType_t           **ppxIdleTaskStackBuffer,
                                   configSTACK_DEPTH_TYPE *puxIdleTaskStackSize)
{
    static StaticTask_t IdleTaskTCBBuffer;
    static StackType_t  IdleTaskStackBuffer[configMINIMAL_STACK_SIZE];

    *ppxIdleTaskTCBBuffer   = &IdleTaskTCBBuffer;
    *ppxIdleTaskStackBuffer = IdleTaskStackBuffer;
    *puxIdleTaskStackSize   = configMINIMAL_STACK_SIZE;
}

void vApplicationGetTimerTaskMemory(StaticTask_t          **ppxTimerTaskTCBBuffer,
                                    StackType_t           **ppxTimerTaskStackBuffer,
                                    configSTACK_DEPTH_TYPE *puxTimerTaskStackSize)
{
    static StaticTask_t TimerTaskTCBBuffer;
    static StackType_t  TimerTaskStackBuffer[configTIMER_TASK_STACK_DEPTH];

    *ppxTimerTaskTCBBuffer   = &TimerTaskTCBBuffer;
    *ppxTimerTaskStackBuffer = TimerTaskStackBuffer;
    *puxTimerTaskStackSize   = configTIMER_TASK_STACK_DEPTH;
}

/*
 * The kernel calls this from inside its task switch, with the scheduler's lists
 * in use, so it must not change kernel state: vTaskEndScheduler() there would
 * delete the idle task the switch is about to pick from. It halts instead.
 */
// pcTaskName must stay non-const to match the kernel's declaration of this hook
// cppcheck-suppress constParameterPointer
void vApplicationStackOverflowHook(TaskHandle_t xTask, char *pcTaskName)
{
    (void)xTask;

    OS_FreeRTOS_StackOverflow(pcTaskName);
}

/*----------------------------------------------------------------
   OS_BSP_StartupTask

   FreeRTOS does not run any created task until vTaskStartScheduler()
   is called, and that call does not return during normal operation -
   so the application entry points must run from within a task of
   their own, rather than directly from main().
 ------------------------------------------------------------------*/
// pvParameters must stay non-const to match FreeRTOS's TaskFunction_t signature
// cppcheck-suppress constParameterCallback
static void OS_BSP_StartupTask(void *pvParameters)
{
    /* This task only runs once the scheduler is up, see SchedulerRan in generic_freertos_bsp_internal.h */
    OS_BSP_GenericFreeRTOSGlobal.SchedulerRan = true;

    /*
     * Call application specific entry point.
     * This should set up all user tasks and resources, then return
     */
    OS_Application_Startup();

    /*
     * OS_Application_Run() implements the background task.
     * The user application may provide this, or a default implementation
     * is used which just calls OS_IdleLoop().
     */
    OS_Application_Run();

    /* The application has finished */
    OS_BSP_Shutdown_Impl();
}

/*----------------------------------------------------------------
   OS_BSP_StorageIsValid

   Checks the storage configuration against the rules littlefs asserts when it
   mounts, so a bad geometry fails startup with a message instead of an assert
   in the middle of a mount. Every size is checked for zero before it is
   divided by.
 ------------------------------------------------------------------*/
static bool OS_BSP_StorageIsValid(const struct lfs_config *Config)
{
    return Config->read_size != 0 && Config->prog_size != 0 && Config->block_size != 0 && Config->block_count != 0
           && Config->cache_size != 0 && Config->lookahead_size != 0 && Config->block_size % Config->read_size == 0
           && Config->block_size % Config->prog_size == 0 && Config->cache_size % Config->read_size == 0
           && Config->cache_size % Config->prog_size == 0 && Config->block_size % Config->cache_size == 0
           && Config->lookahead_size % 8 == 0 && Config->read_buffer != NULL && Config->prog_buffer != NULL
           && Config->lookahead_buffer != NULL;
}

/******************************************************************************
**
**  Purpose:
**    BSP Application entry point.
**
**  Arguments:
**    (none)
**
**  Return:
**    (none)
*/
int main(int argc, char *argv[])
{
    /*
     * Initially clear the global objects
     */
    memset(&OS_BSP_Global, 0, sizeof(OS_BSP_Global));
    /* Every member before StorageConfig, the last one, which is set up below */
    memset(&OS_BSP_GenericFreeRTOSGlobal, 0, offsetof(OS_BSP_GenericFreeRTOSGlobalData_t, StorageConfig));

    /*
     * The littlefs configuration. Static, since littlefs keeps a pointer to it
     * for as long as the volume is mounted, and main()'s stack is reused by
     * interrupts once the scheduler starts.
     */
    static struct lfs_config StorageConfig;

    OS_BSP_GenericFreeRTOSGlobal.StorageConfig = &StorageConfig;

    /* Fill every member of the littlefs configuration from the vendor's storage functions */
    OS_BSP_GenericFreeRTOSGlobal.StorageConfig->read             = OS_BSP_Storage_Read;
    OS_BSP_GenericFreeRTOSGlobal.StorageConfig->prog             = OS_BSP_Storage_Prog;
    OS_BSP_GenericFreeRTOSGlobal.StorageConfig->erase            = OS_BSP_Storage_Erase;
    OS_BSP_GenericFreeRTOSGlobal.StorageConfig->sync             = OS_BSP_Storage_Sync;
    OS_BSP_GenericFreeRTOSGlobal.StorageConfig->read_size        = OS_BSP_Storage_ReadSize();
    OS_BSP_GenericFreeRTOSGlobal.StorageConfig->prog_size        = OS_BSP_Storage_ProgSize();
    OS_BSP_GenericFreeRTOSGlobal.StorageConfig->block_size       = OS_BSP_Storage_BlockSize();
    OS_BSP_GenericFreeRTOSGlobal.StorageConfig->block_count      = OS_BSP_Storage_BlockCount();
    OS_BSP_GenericFreeRTOSGlobal.StorageConfig->block_cycles     = OS_BSP_Storage_BlockCycles();
    OS_BSP_GenericFreeRTOSGlobal.StorageConfig->cache_size       = OS_BSP_Storage_CacheSize();
    OS_BSP_GenericFreeRTOSGlobal.StorageConfig->lookahead_size   = OS_BSP_Storage_LookaheadSize();
    OS_BSP_GenericFreeRTOSGlobal.StorageConfig->read_buffer      = OS_BSP_Storage_ReadBuffer();
    OS_BSP_GenericFreeRTOSGlobal.StorageConfig->prog_buffer      = OS_BSP_Storage_ProgBuffer();
    OS_BSP_GenericFreeRTOSGlobal.StorageConfig->lookahead_buffer = OS_BSP_Storage_LookaheadBuffer();

    if (!OS_BSP_StorageIsValid(OS_BSP_GenericFreeRTOSGlobal.StorageConfig))
    {
        /* littlefs would assert on this configuration when the file system is mounted */
        OS_BSP_ReportString("STORAGE CONFIG INVALID\n");
        return EXIT_FAILURE;
    }

    /*
     * Save the argc/argv arguments for future use.
     */
    OS_BSP_Global.ArgC = argc;
    OS_BSP_Global.ArgV = argv;

    OS_BSP_GenericFreeRTOSGlobal.ConsoleMutex =
        xSemaphoreCreateMutexStatic(&OS_BSP_GenericFreeRTOSGlobal.ConsoleMutexBuffer);

    /*
     * Create the initial task, which performs application startup and then
     * runs the application's main loop.  vTaskStartScheduler() below is what
     * actually begins executing it.
     */
    if (xTaskCreate(OS_BSP_StartupTask,
                    "OSAL_Startup",
                    (configMINIMAL_STACK_SIZE * 4),
                    NULL,
                    (configMAX_PRIORITIES / 2),
                    NULL)
        != pdPASS)
    {
        /* Without this task the scheduler would run forever with nothing to do */
        return EXIT_FAILURE;
    }

    vTaskStartScheduler();

    /*
     * Only reached if the scheduler could not start (e.g. insufficient heap
     * for the idle/timer tasks), or if it was ended after running. Failing to
     * start is an error exit, and no application ran to set a status of its own;
     * an ended scheduler keeps the status the application set.
     */
    if (!OS_BSP_GenericFreeRTOSGlobal.SchedulerRan)
    {
        OS_BSP_SetExitCode(OS_ERROR);
    }

    return OS_BSP_GetReturnStatus();
}
